    "translation": "[चन्द्रस्वरूपं निजचक्षुषैव] [पृथ्वीमें गड़े हुए धनको प्राप्त करनेके लिये जैसे] प्रथम किसी विश्वसनीय पुरुषके कथनकी और फिर पृथिवीको खोदने, कंकड़-पत्थर आदिको हटाने तथा [प्राप्त हुए धनको] स्वीकार करनेकी आवश्यकता होती है—कोरी बातोंसे वह बाहर नहीं निकलता, उसी प्रकार समस्त मायिक-प्रपंचसे शून्य निर्मल आत्मतत्त्व भी ब्रह्मवित् गुरुके उपदेश तथा उसके मनन और निदिध्यासनादिसे ही प्राप्त होता है, थोथी बातोंसे नहीं।",
