    "translation": "[सैषा निदानं पुरुषस्य संसृते-] तमसे ग्रस्त हुआ पुरुष अति बुद्धिमान्, विद्वान्, चतुर और शास्त्रके अत्यन्त सूक्ष्म अर्थोंको देखनेवाला भी हो तो भी वह नाना प्रकार समझानेसे भी अच्छी तरह नहीं समझता; वह भ्रमसे आरोपित किये हुए पदार्थोंको ही सत्य समझता है और उन्हींके गुणोंका आश्रय लेता है। अहो! दुरन्त तमोगुणकी यह महती आवरण-शक्ति बड़ी ही प्रबल है।",
