    "sanskrit": "विज्ञानकोशोऽयमतिप्रकाश: प्रकृष्टसान्निध्यवशात्परात्मन: । यदात्मधी: संसरति भ्रमेण॥ १९०॥",
    "transliteration": "vijñānakośo'yamatiprakāśa: prakṛṣṭasānnidhyavaśātparātmana: yadātmadhī: saṃsarati bhrameṇa 190 ||",
    "translation": "[अतो भवत्येष उपाधिरस्य] यह अहंस्वभाववाला विज्ञानमय कोश ही अनादिकालीन जीव और संसारके समस्त व्यवहारोंका निर्वाह करनेवाला है। यह अपनी पूर्व-वासनासे पुण्य-पापमय अनेकों कर्म करता और उनके फल भोगता है तथा विचित्र योनियोंमें भ्रमण करता हुआ कभी नीचे आता और कभी ऊपर जाता है। जाग्रत्, स्वप्न आदि अवस्थाएँ, सुख-दु:ख आदि भोग, देहादिसे सम्बन्धित आश्रमादिके धर्म-कर्म, गुणोंका अभिमान और ममता आदि सर्वदा इस विज्ञानमय कोशमें ही रहते हैं। यह आत्माकी अति निकटताके कारण अत्यन्त प्रकाशमय है; अत: यह इसकी उपाधि है, जिसमें भ्रमसे आत्मबुद्धि करके यह जन्म-मरणरूप संसारचक्रमें पड़ता है।",
