    "id": 209,
    "sanskrit": "आनन्दप्रतिविम्बचुम्बिततनुर्वृत्तिस्तमोजृम्भिता स्यादानन्दमय: प्रियादिगुणक: स्वेष्टार्थलाभोदय:। पुण्यस्यानुभवे विभाति कृतिनामानन्दरूप: स्वयं भूत्वा नन्दति यत्र साधु तनुभृन्मात्र: प्रयत्नं विना॥ २०९॥",
    "transliteration": "ānandaprativimbacumbitatanurvṛttistamojṛmbhitā syādānandamaya: priyādiguṇaka: sveṣṭārthalābhodaya: puṇyasyānubhave vibhāti kṛtināmānandarūpa: svayaṃ bhūtvā nandati yatra sādhu tanubhṛnmātra: prayatnaṃ vinā 209 ||",
