    "translation": "[विज्ञाय सम्यङ्निजरूपमेतत्] विद्वान् पुरुष घड़ा, जल और उसमें स्थित सूर्यका प्रतिविम्ब—इन सबको छोड़कर जैसे इन तीनोंके प्रकाशक इनसे पृथक् और स्वयंप्रकाशरूप सूर्यको देखता है, उसी प्रकार देह, बुद्धि और चिदाभास—इन तीनोंको छोड़कर बुद्धिगुहामें स्थित साक्षीरूप इस आत्माको अखण्डबोधस्वरूप, सबके प्रकाशक और सत्-असत् दोनोंसे भिन्न, नित्य, विभु, सर्वगत, सूक्ष्म, भीतर-बाहरके भेदसे रहित और अपने-आपसे सर्वथा अभिन्न इस-(आत्मा) को भलीभाँति अपना निजरूप जानकर पुरुष पापरहित, निर्मल और अमर हो जाता है।",
