    "translation": "[दृश्याग्रहे सत्युपपद्यतेऽसौ] जो लोग देहात्म-बुद्धिसे स्थित रहकर बाह्य पदार्थोंकी मनमें आसक्ति रखकर उन्हींके लिये निरन्तर काममें लगे रहते हैं उनको दृश्यकी अप्रतीति कैसे हो सकती है? इसलिये नित्यानन्दके इच्छुक तत्त्वज्ञानीको चाहिये कि वह समस्त धर्म, कर्म एवं विषयोंको त्यागकर निरन्तर आत्मनिष्ठामें तत्पर हो अपने आत्मामें प्रतीत होनेवाले इस दृश्य-प्रपंचका प्रयत्नपूर्वक बाध करे।",
