    "translation": "[छिनत्ति मायाकृतमोहबन्धं] आवरणशक्तिकी पूर्ण निवृत्तिके बिना विक्षेप-शक्तिपर विजय प्राप्त करना अत्यन्त कठिन है। दूध और जलके समान द्रष्टा और दृश्यके अलग-अलग होनेका स्पष्ट ज्ञान हो जानेपर आत्मामें छायी हुई वह आवरण-शक्ति अपने-आप ही नष्ट हो जाती है। यदि मिथ्या दीखनेवाले [इन बुद्धि आदि] पदार्थोंमें द्रष्टा और दृश्य पदार्थोंके स्वरूपको पृथक्-पृथक् करके, स्पष्ट बोधके कारण होनेवाला नि:सन्देहपूर्वक बाधरहित पूर्ण विवेक हो जाय तो फिर विक्षेप नहीं होता और वह विवेक मायाजनित मोहबन्धनको भी काट डालता है; जिससे मुक्त हुए पुरुषको फिर [ जन्म-मरणरूप ] संसारकी प्राप्ति नहीं होती।",
