    "translation": "[प्रबुद्धतत्त्वस्य हि बन्धमुक्ति-] जितेन्द्रिय पुरुषके लिये वैराग्यसे बढ़कर सुखदायक मुझे और कुछ भी प्रतीत नहीं होता और वह यदि कहीं शुद्ध आत्मज्ञानके सहित हो तब तो स्वर्गीय साम्राज्यके सुखका देनेवाला होता है। यह मुक्तिरूप कामिनीका निरन्तर खुला हुआ द्वार है; इसलिये हे वत्स! तुम अपने कल्याणके लिये सब ओरसे इच्छारहित होकर सदा सच्चिदानन्द ब्रह्ममें ही अपनी बुद्धि स्थिर करो।",
