    "id": 395,
    "sanskrit": "वक्तव्यं किमु विद्यतेऽत्र बहुधा ब्रह्मैव जीव: स्वयं ब्रह्मैतज्जगदाततं नु सकलं ब्रह्माद्वितीयं श्रुते:। ब्रह्मैवाहमिति प्रबुद्धमतय: सन्त्यक्तबाह्या: स्फुटं ब्रह्मीभूय वसन्ति सन्ततचिदानन्दात्मनैव ध्रुवम्॥ ३९५॥",
    "transliteration": "vaktavyaṃ kimu vidyate'tra bahudhā brahmaiva jīva: svayaṃ brahmaitajjagadātataṃ nu sakalaṃ brahmādvitīyaṃ śrute: brahmaivāhamiti prabuddhamataya: santyaktabāhyā: sphuṭaṃ brahmībhūya vasanti santatacidānandātmanaiva dhruvam 395 ||",
    "translation": "[आकाशवन्निर्मलनिर्विकल्प-] इस विषयमें और अधिक क्या कहना है? जीव तो स्वयं ब्रह्म ही है और ब्रह्म ही यह सम्पूर्ण जगत्-रूपसे फैला हुआ है, क्योंकि श्रुति भी कहती है कि ब्रह्म अद्वितीय है। और यह निश्चय है, जिनको यह बोध हुआ है कि मैं ब्रह्म ही हूँ वे बाह्य विषयोंको सर्वथा त्यागकर ब्रह्मभावसे सदा सच्चिदानन्दस्वरूपसे ही स्थित रहते हैं।",
