    "translation": "[तज्ज्ञाज्ञयोर्यन्मृगतृष्णिकादौ] [ ‘तत्त्वमसि’ आदि महावाक्योंसे ] शोधित ब्रह्म और आत्माकी एकताको ग्रहण करनेवाली विकल्परहित चिन्मात्र-वृत्तिको प्रज्ञा कहते हैं। यह चिन्मात्र-वृत्ति जिसकी स्थिर हो जाती है, वही जीवन्मुक्त कहा जाता है।",
