    "translation": "[रज्जोर्यथारोपितवस्तुसङ्ग-] मनुष्योंके कर्मोंमें जैसे सूर्यका साक्षीभाव है, लोहेके जलानेमें जैसे अग्निकी दाहकता है और आरोपित सर्पादिसे जैसे रज्जुका संग है, वैसे ही मुझ कूटस्थ चेतन आत्माका विषयोंमें साक्षीभाव है। [अर्थात् जैसे उनकी प्रवृत्तियाँ स्वाभाविक हैं, क्रियमाण नहीं, वैसे ही आत्माका साक्षीभाव भी विषयोंकी अपेक्षासे स्वाभाविक है, वह उसकी क्रिया नहीं है।]",
